package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ClientNameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property client name of trusted client ")
  void test_client_name_v_o_builder() {
    Assertions.assertFalse(ClientNameVO.nullValue().getClientName().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ClientNameVO.tryFrom(null).getClientName().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", ClientNameVO.from("one").getClientName().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ClientNameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ClientNameVO.from("one").toString());
  }
}
